import{_ as e,A as i,q as a,B as l,aV as o,H as c}from"./chunks/framework.B_e8lQlv.js";const d=JSON.parse('{"title":"Tailwind CSS","description":"","frontmatter":{},"headers":[],"relativePath":"guide/project/tailwindcss.md","filePath":"guide/project/tailwindcss.md"}');const t=e({name:"guide/project/tailwindcss.md"},[["render",function(e,d,t,n,s,r){const p=i("NolebaseGitContributors"),u=i("NolebaseGitChangelog");return a(),l("div",null,[d[0]||(d[0]=o('<h1 id="tailwind-css" tabindex="-1">Tailwind CSS <a class="header-anchor" href="#tailwind-css" aria-label="Permalink to &quot;Tailwind CSS&quot;">​</a></h1><p><a href="https://tailwindcss.com/" target="_blank" rel="noreferrer">Tailwind CSS</a> 是一个实用性优先的 CSS 框架，用于快速构建自定义设计。当前项目使用的是 <strong>Tailwind CSS v4</strong>。</p><h2 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h2><p>项目当前不再通过 <code>tailwind.config.*</code> 文件维护 Tailwind 配置，主题与扫描范围都统一放在 CSS 与共享 Vite 配置中。</p><ul><li>主题入口：<code>internal/tailwind-config/src/theme.css</code></li><li>Vite 集成：<code>internal/vite-config</code></li></ul><p>在 <code>global.css</code> 中你会看到当前项目使用的 Tailwind CSS v4 指令，例如：</p><ul><li><code>@source</code></li><li><code>@custom-variant</code></li><li><code>@theme</code></li><li><code>@theme inline</code></li><li><code>@utility</code></li></ul><h2 id="包使用-tailwind-css-的方式" tabindex="-1">包使用 Tailwind CSS 的方式 <a class="header-anchor" href="#包使用-tailwind-css-的方式" aria-label="Permalink to &quot;包使用 Tailwind CSS 的方式&quot;">​</a></h2><p>当前项目不会根据某个包下是否存在 <code>tailwind.config.mjs</code> 来决定是否启用 Tailwind CSS。</p><p>应用和包统一复用 <code>@vben/vite-config</code>，并由该配置接入 <code>@tailwindcss/vite</code>。Tailwind 的扫描范围则统一在 <code>@vben/tailwind-config</code> 对应的 <code>internal/tailwind-config/src/theme.css</code> 中维护。</p><div class="tip custom-block"><p class="custom-block-title">包使用 Tailwind CSS 的说明</p><p>如果你是纯粹的 SDK 包，不需要使用 Tailwind CSS，则无需额外增加旧版 <code>tailwind.config.*</code> 文件。</p></div><h2 id="vue-sfc-中的-apply" tabindex="-1">Vue SFC 中的 <code>@apply</code> <a class="header-anchor" href="#vue-sfc-中的-apply" aria-label="Permalink to &quot;Vue SFC 中的 `@apply`&quot;">​</a></h2><p>项目对 Vue 单文件组件中的 <code>@apply</code> 做了统一处理，相关逻辑位于：</p><ul><li><code>internal/vite-config/src/plugins/tailwind-reference.ts</code></li></ul><p>当组件样式中使用 <code>@apply</code> 时，会自动注入 <code>@reference &quot;@vben/tailwind-config/theme&quot;</code>，一般不需要手动补充。</p>',15)),c(p),c(u)])}]]);export{d as __pageData,t as default};
